import matplotlib.pyplot as plt
import pandas as pd

def task_func(temperatures):
    try:
        if not isinstance(temperatures, pd.DataFrame) or temperatures.empty:
            raise ValueError("Input temperatures must be a non-empty pandas DataFrame.")
        if 'temperature' not in temperatures.columns:
            raise ValueError("Input DataFrame must contain a 'temperature' column.")
        if not isinstance(temperatures.index, pd.DatetimeIndex):
            raise ValueError("Input DataFrame must have a DatetimeIndex.")
    except AttributeError:
        raise ValueError("Input is not in the expected format.")

    plt.rcParams['font.family'] = 'Arial'

    fig, ax = plt.subplots(figsize=(10, 6))
    ax.plot(temperatures.index, temperatures['temperature'])
    ax.set_xlabel('Date', fontname='Arial')
    ax.set_ylabel('Temperature (°C)', fontname='Arial')
    ax.set_title('Daily Temperatures in New York', fontname='Arial')

    return ax

